1	export type Scenario = {
2	  customer: { yearsWithMHPCO: number };
3	  steps: { op: string; items: { type: string }[] }[];
4	};
5	
6	export type ScenarioResult = {
7	  results: { premium: number }[];
8	};
9	
10	const PROCESSING_FEE = 5;
11	
12	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
13	
14	const BASE_PREMIUMS: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	  moonstone: 25,
21	};
22	
23	// Percentages stay in integer percent points: multiply first, divide by 100
24	// last. A float multiplier such as `base * 1.1` yields 110.00000000000001 for
25	// a sword and breaks the ceil. `(base * 110) / 100` gives exactly 110.
26	const increasedBy = (amount: number, percent: number): number =>
27	  (amount * (100 + percent)) / 100;
28	
29	const BLOCK_SIZE = 3;
30	const BLOCK_BASE_PREMIUM = 60;
31	
32	const countByType = (items: { type: string }[]): Map<string, number> => {
33	  const counts = new Map<string, number>();
34	
35	  for (const item of items) {
36	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
37	  }
38	
39	  return counts;
40	};
41	
42	const policyBaseOf = (items: { type: string }[]): number => {
43	  let total = 0;
44	
45	  for (const [type, count] of countByType(items)) {
46	    total +=
47	      count === BLOCK_SIZE
48	        ? BLOCK_BASE_PREMIUM
49	        : count * BASE_PREMIUMS[type];
50	  }
51	
52	  return total;
53	};
54	
55	const withFirstInsuranceSurcharge = (policyBase: number): number =>
56	  increasedBy(policyBase, FIRST_INSURANCE_SURCHARGE_PERCENT);
57	
58	const quote = (items: { type: string }[]): number => {
59	  const surcharged = withFirstInsuranceSurcharge(policyBaseOf(items));
60	
61	  // Rounding is in the MHPCO's favour: premiums round up.
62	  return Math.ceil(surcharged) + PROCESSING_FEE;
63	};
64	
65	export const runScenario = (scenario: Scenario): ScenarioResult => ({
66	  results: scenario.steps.map((step) => ({ premium: quote(step.items) })),
67	});
