const baseOfGroup = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];

const policyBaseOf = (items: { type: string }[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + baseOfGroup(type, count),
    0,
  );
